export function translateHostControls() {
  const roots = ['toolbar', 'inspector', 'findbar', 'formatDock', 'contextMenu', 'alert-overlay', 'alert-modal', 'viewbar', 'contextbar', 'empty', 'toast', 'spellbar']
    .map(id => document.getElementById(id)).filter(Boolean);
  const excluded = node => node.parentElement?.closest('input, textarea, [contenteditable="true"], canvas');
  const translate = root => {
    if (!root) return;
    if (root.nodeType === Node.TEXT_NODE) {
      if (excluded(root)) return;
      const text = root.textContent.trim().replace(/\s+/g,' ');
      if (words[text]) root.textContent = words[text];
      return;
    }
    if (root.nodeType !== Node.ELEMENT_NODE) return;
    for (const element of [root, ...root.querySelectorAll('[title], [aria-label], [placeholder]')]) {
      for (const attribute of ['title', 'aria-label', 'placeholder']) {
        const value = element.getAttribute(attribute);
        if (words[value]) element.setAttribute(attribute, words[value]);
      }
    }
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) translate(node);
  };
  for (const root of roots) {
    translate(root);
    new MutationObserver(changes => {
      for (const change of changes) {
        if (change.type === 'childList') for (const node of change.addedNodes) translate(node);
        else translate(change.target);
      }
    }).observe(root, { childList: true, subtree: true, characterData: true, attributes: true,
                       attributeFilter: ['title', 'aria-label', 'placeholder'] });
  }
  const open = document.querySelector('label[for="file"]');
  if (open) open.hidden = true;
}
